#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

struct Point {
   double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0u, 0u, 0u, 0u};

    const int max_threads = omp_get_max_threads();
    std::vector<std::array<size_t, 4>> local(static_cast<size_t>(max_threads),
                                             std::array<size_t, 4>{0u, 0u, 0u, 0u});

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &lb = local[static_cast<size_t>(tid)];

        #pragma omp for schedule(static)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(points.size()); ++i) {
            const double x = points[static_cast<size_t>(i)].x;
            const double y = points[static_cast<size_t>(i)].y;

            // Treat points on axes as in the "positive" side (>= 0).
            // Quadrant mapping: 0:(+,+), 1:(-,+), 2:(-,-), 3:(+,-)
            size_t q;
            if (x >= 0.0) {
                q = (y >= 0.0) ? 0u : 3u;
            } else {
                q = (y >= 0.0) ? 1u : 2u;
            }
            lb[q] += 1u;
        }
    }

    for (const auto &lb : local) {
        bins[0] += lb[0];
        bins[1] += lb[1];
        bins[2] += lb[2];
        bins[3] += lb[3];
    }
}
